// Throwaway prototype: download a JusPrin installer with the app's own
// Slic3r::Http, verify its SHA-256, and start it the way the app would.
//
//   updater_proto download <url> <out-file>
//   updater_proto verify   <file> <SHA256SUMS.txt>
//   updater_proto run      create|shell|runas <exe> [args...]
//   updater_proto helper   <pid-to-wait-for> <installer> <app-exe>
//       Waits for the pid to exit, runs "<installer> /S" (ShellExecuteEx),
//       waits for it, then starts <app-exe> through explorer.exe.
// Every step appends a timestamped line to C:\guitest\ipr\log.txt.
#include "slic3r/Utils/Http.hpp"

#include <openssl/evp.h>
#include <windows.h>
#include <shellapi.h>
#include <winver.h>

#include <chrono>
#include <cstdio>
#include <fstream>
#include <iomanip>
#include <sstream>
#include <string>
#include <vector>

static void logln(const std::string& s)
{
    SYSTEMTIME t; GetLocalTime(&t);
    char ts[64];
    snprintf(ts, sizeof ts, "%02d:%02d:%02d.%03d", t.wHour, t.wMinute, t.wSecond, t.wMilliseconds);
    std::ofstream f("C:\\guitest\\ipr\\log.txt", std::ios::app);
    f << ts << " [pid " << GetCurrentProcessId() << "] " << s << "\n";
    printf("%s %s\n", ts, s.c_str());
}

static std::wstring widen(const std::string& s)
{
    int n = MultiByteToWideChar(CP_UTF8, 0, s.c_str(), -1, nullptr, 0);
    std::wstring w(n, 0);
    MultiByteToWideChar(CP_UTF8, 0, s.c_str(), -1, &w[0], n);
    w.resize(n - 1);
    return w;
}

static std::string integrity()
{
    HANDLE tok; OpenProcessToken(GetCurrentProcess(), TOKEN_QUERY, &tok);
    DWORD len = 0; GetTokenInformation(tok, TokenIntegrityLevel, nullptr, 0, &len);
    std::vector<char> buf(len);
    GetTokenInformation(tok, TokenIntegrityLevel, buf.data(), len, &len);
    auto* til = reinterpret_cast<TOKEN_MANDATORY_LABEL*>(buf.data());
    DWORD rid = *GetSidSubAuthority(til->Label.Sid, *GetSidSubAuthorityCount(til->Label.Sid) - 1);
    CloseHandle(tok);
    if (rid >= SECURITY_MANDATORY_SYSTEM_RID) return "system";
    if (rid >= SECURITY_MANDATORY_HIGH_RID) return "high (elevated)";
    if (rid >= SECURITY_MANDATORY_MEDIUM_RID) return "medium (normal user)";
    return "low";
}

static std::string sha256_file(const std::string& path)
{
    std::ifstream f(path, std::ios::binary);
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(ctx, EVP_sha256(), nullptr);
    std::vector<char> buf(1 << 20);
    while (f) {
        f.read(buf.data(), buf.size());
        EVP_DigestUpdate(ctx, buf.data(), size_t(f.gcount()));
    }
    unsigned char md[32]; unsigned int n = 0;
    EVP_DigestFinal_ex(ctx, md, &n);
    EVP_MD_CTX_free(ctx);
    std::ostringstream o;
    for (unsigned i = 0; i < n; ++i) o << std::hex << std::setw(2) << std::setfill('0') << int(md[i]);
    return o.str();
}

static int cmd_download(const std::string& url, const std::string& out)
{
    auto t0 = std::chrono::steady_clock::now();
    logln("download start " + url);
    int rc = 1;
    size_t last_mb = 0;
    Slic3r::Http::get(url)
        .on_progress([&](Slic3r::Http::Progress p, bool&) {
            size_t mb = p.dlnow >> 20;
            if (mb >= last_mb + 32) { last_mb = mb; logln("  " + std::to_string(mb) + " MB of " + std::to_string(p.dltotal >> 20)); }
        })
        .on_complete([&](std::string body, unsigned status) {
            std::ofstream f(out, std::ios::binary);
            f.write(body.data(), body.size());
            f.close();
            logln("download done status=" + std::to_string(status) + " bytes=" + std::to_string(body.size()));
            rc = 0;
        })
        .on_error([&](std::string body, std::string err, unsigned status) {
            logln("download error status=" + std::to_string(status) + " " + err);
        })
        .perform_sync();
    double s = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
    logln("download seconds=" + std::to_string(s));
    return rc;
}

static int cmd_verify(const std::string& file, const std::string& sums)
{
    auto t0 = std::chrono::steady_clock::now();
    std::string name = file.substr(file.find_last_of("\\/") + 1);
    std::string got = sha256_file(file), want;
    std::ifstream f(sums);
    for (std::string line; std::getline(f, line);) {
        if (line.size() > 66 && line.find(name) != std::string::npos) want = line.substr(0, 64);
    }
    double s = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
    logln("verify " + name + " want=" + want + " got=" + got + (want == got ? " MATCH" : " MISMATCH") +
          " seconds=" + std::to_string(s));
    return want == got ? 0 : 2;
}

// Returns the process handle, or null.
static HANDLE start(const std::string& how, const std::string& exe, const std::string& args)
{
    logln("start how=" + how + " exe=" + exe + " args=" + args + " my integrity=" + integrity());
    if (how == "create") {
        std::wstring cl = L"\"" + widen(exe) + L"\" " + widen(args);
        STARTUPINFOW si{sizeof si}; PROCESS_INFORMATION pi{};
        if (!CreateProcessW(nullptr, &cl[0], nullptr, nullptr, FALSE, 0, nullptr, nullptr, &si, &pi)) {
            logln("  CreateProcess failed, GetLastError=" + std::to_string(GetLastError()));
            return nullptr;
        }
        CloseHandle(pi.hThread);
        logln("  started pid " + std::to_string(pi.dwProcessId));
        return pi.hProcess;
    }
    std::wstring wexe = widen(exe), wargs = widen(args);
    SHELLEXECUTEINFOW sei{sizeof sei};
    sei.fMask = SEE_MASK_NOCLOSEPROCESS | SEE_MASK_NOASYNC;
    sei.lpVerb = how == "runas" ? L"runas" : L"open";
    sei.lpFile = wexe.c_str();
    sei.lpParameters = wargs.c_str();
    sei.nShow = SW_SHOWNORMAL;
    if (!ShellExecuteExW(&sei)) {
        logln("  ShellExecuteEx failed, GetLastError=" + std::to_string(GetLastError()));
        return nullptr;
    }
    logln("  ShellExecuteEx returned, pid " + std::to_string(sei.hProcess ? GetProcessId(sei.hProcess) : 0));
    return sei.hProcess;
}

static DWORD wait_exit(HANDLE h)
{
    auto t0 = std::chrono::steady_clock::now();
    WaitForSingleObject(h, INFINITE);
    DWORD code = 0; GetExitCodeProcess(h, &code); CloseHandle(h);
    double s = std::chrono::duration<double>(std::chrono::steady_clock::now() - t0).count();
    logln("  exited code=" + std::to_string(code) + " after seconds=" + std::to_string(s));
    return code;
}

static std::string file_version(const std::string& path)
{
    std::wstring w = widen(path);
    DWORD h = 0, n = GetFileVersionInfoSizeW(w.c_str(), &h);
    if (!n) return "unreadable";
    std::vector<char> buf(n);
    GetFileVersionInfoW(w.c_str(), 0, n, buf.data());
    VS_FIXEDFILEINFO* fi = nullptr; UINT len = 0;
    if (!VerQueryValueW(buf.data(), L"\\", reinterpret_cast<void**>(&fi), &len) || !fi) return "none";
    return std::to_string(HIWORD(fi->dwFileVersionMS)) + "." + std::to_string(LOWORD(fi->dwFileVersionMS)) + "." +
           std::to_string(HIWORD(fi->dwFileVersionLS));
}

int main(int argc, char** argv)
{
    std::vector<std::string> a(argv, argv + argc);
    if (a.size() >= 4 && a[1] == "download") return cmd_download(a[2], a[3]);
    if (a.size() >= 4 && a[1] == "verify") return cmd_verify(a[2], a[3]);
    if (a.size() >= 4 && a[1] == "run") {
        std::string args;
        for (size_t i = 4; i < a.size(); ++i) args += (i > 4 ? " " : "") + a[i];
        HANDLE h = start(a[2], a[3], args);
        return h ? int(wait_exit(h)) : 3;
    }
    if (a.size() >= 5 && a[1] == "helper") {
        DWORD pid = DWORD(std::stoul(a[2]));
        logln("helper waiting for pid " + a[2] + ", my integrity=" + integrity());
        if (HANDLE p = OpenProcess(SYNCHRONIZE, FALSE, pid)) { WaitForSingleObject(p, INFINITE); CloseHandle(p); }
        logln("helper: old process gone");
        HANDLE h = start("shell", a[3], "/S");
        if (!h) return 3;
        DWORD code = wait_exit(h);
        logln("helper: installed program file reports version " + file_version(a[4]));
        // The installer's own "Run JusPrin" box goes through explorer.exe for the same reason.
        HANDLE r = start("create", "C:\\Windows\\explorer.exe", "\"" + a[4] + "\"");
        if (r) CloseHandle(r);
        logln("helper done");
        return int(code);
    }
    fprintf(stderr, "usage: see source\n");
    return 64;
}

// THROWAWAY PROTOTYPE: see InstallRestartPrototype.hpp.
#include "InstallRestartPrototype.hpp"

#ifdef _WIN32

#include "slic3r/GUI/MsgDialog.hpp"
#include "slic3r/Utils/Http.hpp"

#include <boost/filesystem.hpp>
#include <boost/log/trivial.hpp>

#include <openssl/evp.h>

#include <wx/progdlg.h>
#include <wx/msw/wrapwin.h>
#include <shellapi.h>

#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iomanip>
#include <sstream>
#include <vector>

namespace Slic3r::GUI::JusPrin::Updates {

namespace fs = boost::filesystem;

namespace {

// The same timeline file the helper writes, so one file shows the whole run.
void timeline(const std::string& line)
{
    SYSTEMTIME t;
    GetLocalTime(&t);
    char ts[32];
    snprintf(ts, sizeof ts, "%02d:%02d:%02d.%03d", t.wHour, t.wMinute, t.wSecond, t.wMilliseconds);
    std::ofstream f("C:\\guitest\\ipr\\log.txt", std::ios::app);
    f << ts << " [app pid " << GetCurrentProcessId() << "] " << line << "\n";
    BOOST_LOG_TRIVIAL(warning) << "install-restart prototype: " << line;
}

std::string sha256_of(const fs::path& file)
{
    std::ifstream in(file.wstring(), std::ios::binary);
    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    EVP_DigestInit_ex(ctx, EVP_sha256(), nullptr);
    std::vector<char> buf(1 << 20);
    while (in) {
        in.read(buf.data(), buf.size());
        EVP_DigestUpdate(ctx, buf.data(), size_t(in.gcount()));
    }
    unsigned char md[32];
    unsigned int  n = 0;
    EVP_DigestFinal_ex(ctx, md, &n);
    EVP_MD_CTX_free(ctx);
    std::ostringstream hex;
    for (unsigned i = 0; i < n; ++i)
        hex << std::hex << std::setw(2) << std::setfill('0') << int(md[i]);
    return hex.str();
}

// Downloads `url` into `out` while `progress` shows it. Returns an error, or
// empty on success.
std::string download(const std::string& url, const fs::path& out, wxProgressDialog& progress)
{
    std::string body, error;
    int         last = -1;
    Http::get(url)
        .on_progress([&](Http::Progress p, bool& cancel) {
            if (p.dltotal == 0)
                return;
            const int permille = int(1000.0 * double(p.dlnow) / double(p.dltotal));
            if (permille != last) {
                last = permille;
                if (!progress.Update(permille))
                    cancel = true;
            }
        })
        .on_complete([&](std::string b, unsigned) { body = std::move(b); })
        .on_error([&](std::string, std::string e, unsigned status) { error = e + " (HTTP " + std::to_string(status) + ")"; })
        .perform_sync();
    if (!error.empty())
        return error;
    std::ofstream f(out.wstring(), std::ios::binary);
    f.write(body.data(), std::streamsize(body.size()));
    return f ? std::string() : "could not write " + out.string();
}

void fail(wxWindow* parent, const std::string& what)
{
    timeline("failed: " + what);
    MessageDialog(parent, wxString::FromUTF8("The update did not install: " + what), "JusPrin update", wxOK | wxICON_ERROR).ShowModal();
}

} // namespace

bool prototype_install_and_restart(wxWindow* parent, const std::string& version)
{
    timeline("clicked: install and restart to " + version);
    const fs::path dir = fs::temp_directory_path() / "JusPrinUpdate";
    fs::create_directories(dir);
    const std::string name      = "JusPrin_Windows_Installer_V" + version + "_x64.exe";
    const std::string base      = "https://github.com/TheSpaghettiDetective/JusPrin/releases/download/jusprin/v" + version + "/";
    const fs::path    installer = dir / name;
    const fs::path    sums      = dir / "SHA256SUMS.txt";

    {
        wxProgressDialog progress("JusPrin update", wxString::FromUTF8("Downloading JusPrin " + version + "…"), 1000, parent,
                                  wxPD_APP_MODAL | wxPD_CAN_ABORT | wxPD_AUTO_HIDE | wxPD_ELAPSED_TIME | wxPD_REMAINING_TIME);
        if (const std::string e = download(base + name, installer, progress); !e.empty()) {
            fail(parent, "download: " + e);
            return false;
        }
        timeline("downloaded " + std::to_string(fs::file_size(installer)) + " bytes");
        if (const std::string e = download(base + "SHA256SUMS.txt", sums, progress); !e.empty()) {
            fail(parent, "checksums: " + e);
            return false;
        }
        progress.Pulse(wxString::FromUTF8("Checking the download…"));
        std::string   want;
        std::ifstream in(sums.wstring());
        for (std::string line; std::getline(in, line);)
            if (line.size() > 66 && line.find(name) != std::string::npos)
                want = line.substr(0, 64);
        const std::string got = sha256_of(installer);
        timeline("sha256 want=" + want + " got=" + got);
        if (want.empty() || want != got) {
            fail(parent, "the download does not match SHA256SUMS.txt");
            return false;
        }
    }

    // The helper runs from the temp folder: the installer replaces this
    // install's folder. On the VM it is the prototype's updater_proto.exe.
    const char*    from   = std::getenv("JUSPRIN_UPDATE_HELPER");
    const fs::path helper = dir / "jusprin-update-helper.exe";
    boost::system::error_code ec;
    fs::copy_file(from ? from : "C:\\guitest\\ipr\\updater_proto.exe", helper, fs::copy_options::overwrite_existing, ec);
    if (ec) {
        fail(parent, "copying the helper: " + ec.message());
        return false;
    }

    wchar_t exe[MAX_PATH];
    GetModuleFileNameW(nullptr, exe, MAX_PATH);
    const std::wstring params = L"helper " + std::to_wstring(GetCurrentProcessId()) + L" \"" + installer.wstring() + L"\" \"" + exe + L"\"";
    const std::wstring file   = helper.wstring();

    SHELLEXECUTEINFOW sei{sizeof sei};
    sei.fMask        = SEE_MASK_NOCLOSEPROCESS | SEE_MASK_NOASYNC;
    sei.hwnd         = parent ? HWND(parent->GetHandle()) : nullptr;
    sei.lpVerb       = L"runas";
    sei.lpFile       = file.c_str();
    sei.lpParameters = params.c_str();
    sei.nShow        = SW_HIDE;
    timeline("asking for administrator rights (UAC)");
    if (!ShellExecuteExW(&sei)) {
        const DWORD code = GetLastError();
        timeline("UAC refused or failed, GetLastError=" + std::to_string(code));
        if (code == ERROR_CANCELLED)
            MessageDialog(parent, "The update was cancelled. JusPrin was not changed.", "JusPrin update", wxOK).ShowModal();
        else
            fail(parent, "starting the helper failed with Windows error " + std::to_string(code));
        return false;
    }
    if (sei.hProcess)
        CloseHandle(sei.hProcess);
    timeline("UAC accepted, helper running; quitting JusPrin");
    return true;
}

} // namespace Slic3r::GUI::JusPrin::Updates

#else

namespace Slic3r::GUI::JusPrin::Updates {
bool prototype_install_and_restart(wxWindow*, const std::string&) { return false; }
} // namespace Slic3r::GUI::JusPrin::Updates

#endif

#pragma once

// THROWAWAY PROTOTYPE, never for jusprin-dev or a release. It measures what an
// in-app "install and restart" costs on Windows, on the GCP test VM.
//
// Downloads the Windows installer of `version` with Slic3r::Http, checks it
// against the release's SHA256SUMS.txt, then starts a helper with a UAC
// request. The helper waits for this process to exit, runs the installer
// silently and reopens JusPrin through Explorer. Returns true when the helper
// is running, so JusPrin should now quit; false when the person cancelled or
// something failed (a dialog has said so).

#include <string>

class wxWindow;

namespace Slic3r::GUI::JusPrin::Updates {

bool prototype_install_and_restart(wxWindow* parent, const std::string& version);

} // namespace Slic3r::GUI::JusPrin::Updates

